@Finset.prod_fiberwise : ∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_3} [inst : CommMonoid M] [inst_1 : DecidableEq κ]
  [inst_2 : Fintype κ] (s : Finset ι) (g : ι → κ) (f : ι → M), ∏ j, ∏ i ∈ s with g i = j, f i = ∏ i ∈ s, f i
@Fintype.prod_sum : ∀ {ι : Type u_1} {R : Type u_2} [inst : Fintype ι] [inst_1 : CommSemiring R]
  [inst_2 : DecidableEq ι] {κ : ι → Type u_3} [inst_3 : (i : ι) → Fintype (κ i)] (f : (i : ι) → κ i → R),
  ∏ i, ∑ j, f i j = ∑ x, ∏ i, f i (x i)
@Nat.not_odd_iff_even : ∀ {n : ℕ}, ¬Odd n ↔ Even n
@Odd.add_one : ∀ {α : Type u_1} [inst : Semiring α] {a : α}, Odd a → Even (a + 1)
@Equiv.prod_comp : ∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_3} [inst : Fintype ι] [inst_1 : Fintype κ]
  [inst_2 : CommMonoid M] (e : ι ≃ κ) (g : κ → M), ∏ i, g (e i) = ∏ i, g i
@Finset.sum_bij : ∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_3} [inst : AddCommMonoid M] {s : Finset ι} {t : Finset κ}
  {f : ι → M} {g : κ → M} (i : (a : ι) → a ∈ s → κ),
  (∀ (a : ι) (ha : a ∈ s), i a ha ∈ t) →
    (∀ (a₁ : ι) (ha₁ : a₁ ∈ s) (a₂ : ι) (ha₂ : a₂ ∈ s), i a₁ ha₁ = i a₂ ha₂ → a₁ = a₂) →
      (∀ b ∈ t, ∃ a, ∃ (ha : a ∈ s), i a ha = b) →
        (∀ (a : ι) (ha : a ∈ s), f a = g (i a ha)) → ∑ x ∈ s, f x = ∑ x ∈ t, g x
@Fintype.card_perm : ∀ {α : Type u_1} [inst : DecidableEq α] [inst_1 : Fintype α],
  Fintype.card (Equiv.Perm α) = (Fintype.card α).factorial
@Finite.injective_iff_surjective : ∀ {α : Type u_1} [Finite α] {f : α → α}, Function.Injective f ↔ Function.Surjective f
@Finset.sum_filter : ∀ {ι : Type u_1} {M : Type u_2} {s : Finset ι} [inst : AddCommMonoid M] (p : ι → Prop)
  [inst_1 : DecidablePred p] (f : ι → M), ∑ a ∈ s with p a, f a = ∑ a ∈ s, if p a then f a else 0

